create extension if not exists pgcrypto;
create extension if not exists postgis;
create type farm_status as enum ('draft_application','submitted','under_review','verification_scheduled','verified','selected','waitlisted','rejected','baseline_pending','planning','active','at_risk','audit_due','judging','completed','awarded','withdrawn');
create table regions (id uuid primary key default gen_random_uuid(), name text not null unique, code text not null unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table districts (id uuid primary key default gen_random_uuid(), region_id uuid not null references regions, name text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(region_id,name));
create table farms (id uuid primary key default gen_random_uuid(), passport_id text not null unique check(passport_id ~ '^KRL-WB-'), region_id uuid not null references regions, district_id uuid not null references districts, constituency text not null, farmer_display_name text not null, farm_type text not null, primary_crop text not null, status farm_status not null, location geography(point,4326), archived_at timestamptz, created_by uuid references auth.users, updated_by uuid references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index farms_location_gix on farms using gist(location); create index farms_region_idx on farms(region_id); create index farms_district_idx on farms(district_id); create index farms_status_idx on farms(status);
create table evidence_assets (id uuid primary key default gen_random_uuid(), farm_id uuid not null references farms, storage_path text not null, caption text, verification_status text not null check(verification_status in ('pending','approved','rejected')), privacy_classification text not null check(privacy_classification in ('private','programme','public')), capture_date date, uploaded_by uuid references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table progress_updates (id uuid primary key default gen_random_uuid(), farm_id uuid not null references farms, stage text not null, summary text not null, work_completed text not null, next_action text, verification_status text not null default 'pending', created_by uuid references auth.users, updated_by uuid references auth.users, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table mentor_visits (id uuid primary key default gen_random_uuid(), farm_id uuid not null references farms, mentor_id uuid references auth.users, scheduled_date date not null, actual_date date, purpose text not null, observations text, recommendations text, farmer_acknowledged boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table kpis (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, pillar text not null check(pillar in ('satya','mangal','sundar','samriddhi')), unit text not null, direction text not null, minimum numeric, maximum numeric, target numeric, weight numeric not null check(weight>0), evidence_required boolean not null default false, config_version text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table kpi_observations (id uuid primary key default gen_random_uuid(), farm_id uuid not null references farms, kpi_id uuid not null references kpis, value numeric, observed_at timestamptz not null, evidence_id uuid references evidence_assets, verified_at timestamptz, created_by uuid references auth.users, created_at timestamptz not null default now());
create table score_versions (id uuid primary key default gen_random_uuid(), farm_id uuid not null references farms, version integer not null, config_version text not null, satya numeric check(satya between 0 and 100), mangal numeric check(mangal between 0 and 100), sundar numeric check(sundar between 0 and 100), samriddhi numeric check(samriddhi between 0 and 100), final_score numeric check(final_score between 0 and 100), status text not null check(status in ('provisional','verified','approved','locked')), override_reason text, approved_by uuid references auth.users, created_at timestamptz not null default now(), unique(farm_id,version));
create table activity_events (id uuid primary key default gen_random_uuid(), farm_id uuid references farms, actor_id uuid references auth.users, event_type text not null, summary text not null, created_at timestamptz not null default now());
alter table regions enable row level security; alter table districts enable row level security; alter table farms enable row level security; alter table evidence_assets enable row level security; alter table progress_updates enable row level security; alter table mentor_visits enable row level security; alter table score_versions enable row level security;
create policy "authenticated farms by region" on farms for select to authenticated using (region_id::text = any(coalesce(string_to_array(auth.jwt()->>'region_ids',','),array[region_id::text])));
create policy "public approved evidence" on evidence_assets for select to anon using (privacy_classification='public' and verification_status='approved');
